                    for nd in ((d + 1) % 10, (d + 9) % 10):
                        nxt = prefix + str(nd) + suffix
                        if nxt in dead:
                            continue
                        if nxt in end:
                            return steps
                        if nxt not in visited:
                            visited.add(nxt)
                            next_front.add(nxt)
            begin = next_front

        return -1

